#include <stdint.h>
#include <string.h>

static inline uint32_t nan_canon(float f) {
    uint32_t u;
    memcpy(&u, &f, 4);
    if ((u & 0x7F800000) == 0x7F800000 && (u & 0x007FFFFF) != 0) {
        return 0x7FC00000;
    }
    return u;
}

static inline float f32_mul(float a, float b) {
    float r = a * b;
    uint32_t u = nan_canon(r);
    memcpy(&r, &u, 4);
    return r;
}

static inline float f32_add(float a, float b) {
    float r = a + b;
    uint32_t u = nan_canon(r);
    memcpy(&r, &u, 4);
    return r;
}

void fdot2_custom_model(const uint32_t in[5], uint32_t out[5]) {
    float a0, a1, b0, b1, c;
    memcpy(&a0, &in[0], 4);
    memcpy(&a1, &in[1], 4);
    memcpy(&b0, &in[2], 4);
    memcpy(&b1, &in[3], 4);
    memcpy(&c, &in[4], 4);

    float p0 = f32_mul(a0, b0);
    float p1 = f32_mul(a1, b1);
    float s0 = f32_add(c, p0);
    float res = f32_add(s0, p1);

    uint32_t res_u = nan_canon(res);
    memcpy(&out[0], &res_u, 4);
    out[1] = 0;
    out[2] = 0;
    out[3] = 0;
    out[4] = 0;
}

