    inline float u32_to_f32(uint32_t u) {
        float f;
        std::memcpy(&f, &u, sizeof(f));
        return f;
    }

    inline uint32_t f32_to_u32(float f) {
        uint32_t u;
        std::memcpy(&u, &f, sizeof(u));
        return u;
    }

    inline float f32_mul(float a, float b) {
        float r = a * b;
        uint32_t ru = f32_to_u32(r);
        if ((ru & 0x7F800000) == 0x7F800000 && (ru & 0x007FFFFF) != 0) {
            return u32_to_f32(0x7FC00000);
        }
        return r;
    }

    inline float f32_add(float a, float b) {
        float r = a + b;
        uint32_t ru = f32_to_u32(r);
        if ((ru & 0x7F800000) == 0x7F800000 && (ru & 0x007FFFFF) != 0) {
            return u32_to_f32(0x7FC00000);
        }
        return r;
    }
}

void fdot2_custom_iss(const uint32_t in[5], uint32_t out[5]) {
